/**
 * Master/Detail Core Logic
 *
 * Pure functions for managing detail row expansion state.
 */
/**
 * Toggle the expansion state of a detail row.
 * Mutates the Set in-place and returns it (avoids O(n) copy per toggle).
 */
export declare function toggleDetailRow(expandedRows: Set<object>, row: object): Set<object>;
/**
 * Expand a detail row.
 * Mutates the Set in-place and returns it (avoids O(n) copy).
 */
export declare function expandDetailRow(expandedRows: Set<object>, row: object): Set<object>;
/**
 * Collapse a detail row.
 * Mutates the Set in-place and returns it (avoids O(n) copy).
 */
export declare function collapseDetailRow(expandedRows: Set<object>, row: object): Set<object>;
/**
 * Check if a detail row is expanded.
 */
export declare function isDetailExpanded(expandedRows: Set<object>, row: object): boolean;
/**
 * Create a detail element for a given row.
 * The element spans all columns and contains the rendered content.
 */
export declare function createDetailElement(row: any, rowIndex: number, renderer: (row: any, rowIndex: number) => HTMLElement | string, columnCount: number): HTMLElement;
